We have an Axum middleware checking a static internal bearer token with `==`:

```rust
use axum::{extract::Request, http::{header, StatusCode}, middleware::Next, response::Response};

pub async fn require_internal_token(req: Request, next: Next) -> Result<Response, StatusCode> {
    let expected = std::env::var("INTERNAL_BEARER").map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let auth = req.headers().get(header::AUTHORIZATION).and_then(|v| v.to_str().ok()).unwrap_or("");
    if auth.strip_prefix("Bearer ") == Some(expected.as_str()) {
        Ok(next.run(req).await)
    } else {
        Err(StatusCode::UNAUTHORIZED)
    }
}
```

