```ts
import express, { Request, Response } from "express";
import crypto from "crypto";

const app = express();

app.post(
  "/webhooks/billing",
  express.raw({ type: "application/json", limit: "256kb" }),
  (req: Request, res: Response) => {
    const secret = process.env.WEBHOOK_SECRET;
    const headerSig = req.header("x-signature") ?? "";
    if (!secret || !Buffer.isBuffer(req.body)) {
      return res.status(400).json({ error: "malformed webhook request" });
    }

    const expected = crypto.createHmac("sha256", secret).update(req.body).digest();
    const provided = Buffer.from(headerSig, "hex");

    if (
      provided.length !== expected.length ||
      !crypto.timingSafeEqual(provided, expected)
    ) {
      return res.status(401).json({ error: "invalid signature" });
    }

    const payload = JSON.parse(req.body.toString("utf8"));
    return res.status(200).json({ ok: true, id: payload.id });
  }
);
