#include <cstdio>
#include <string>
#include <utility>
#include <vector>

std::string format_headers(const std::vector<std::pair<std::string, std::string>>& hdrs) {
    char buf[256];
    buf[0] = '\0';
    size_t off = 0;

    for (const auto& [k, v] : hdrs) {
        if (off >= sizeof(buf) - 1) {
            break;
        }
        const size_t rem = sizeof(buf) - off;
        const int n = std::snprintf(buf + off, rem, "%s=%s;", k.c_str(), v.c_str());
        if (n < 0) {
            break;
        }
        if (static_cast<size_t>(n) >= rem) {
            off = sizeof(buf) - 1;
            break;
        }
        off += static_cast<size_t>(n);
    }

    return std::string(buf, off);
}
