export class TenantRequestTracker {
  private readonly counts = new Map<string, number>();
  private readonly maxTenants: number;

  constructor(maxTenants = 10_000) {
    this.maxTenants = maxTenants;
  }

  record(tenantKey: string): number {
    const cleanKey = tenantKey.trim();
    if (!cleanKey || cleanKey.length > 128) {
      throw new Error("Invalid tenant key");
    }
    const existing = this.counts.get(cleanKey);
    if (existing === undefined && this.counts.size >= this.maxTenants) {
      throw new Error("Tenant tracker capacity reached");
    }
    const next = (existing ?? 0) + 1;
    this.counts.set(cleanKey, next);
    return next;
  }

  getCount(tenantKey: string): number {
    return this.counts.get(tenantKey) ?? 0;
  }
}
