Our Go archive importer extracts user-uploaded `.zip` bundles using `filepath.Join(destDir, f.Name)`:

```go
package importer

import (
	"archive/zip"
	"io"
	"os"
	"path/filepath"
)

func ExtractBundle(zipPath, destDir string) error {
	r, err := zip.OpenReader(zipPath)
	if err != nil {
		return err
	}
	defer r.Close()

	for _, f := range r.File {
		outPath := filepath.Join(destDir, f.Name)
		if f.FileInfo().IsDir() {
			os.MkdirAll(outPath, 0755)
			continue
		}
		os.MkdirAll(filepath.Dir(outPath), 0755)
		dst, _ := os.Create(outPath)
		rc, _ := f.Open()
		io.Copy(dst, rc)
		rc.Close()
		dst.Close()
	}
	return nil
}
```

How do we harden this against zip-slip path traversal, symlink entries, and decompression bombs?

