```go
package importer

import (
	"archive/zip"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const maxEntryBytes int64 = 16 << 20

func ExtractBundle(zipPath, destDir string) error {
	root := filepath.Clean(destDir)
	if err := os.MkdirAll(root, 0750); err != nil {
		return err
	}
	prefix := root + string(os.PathSeparator)

	r, err := zip.OpenReader(zipPath)
	if err != nil {
		return err
	}
	defer r.Close()

	for _, f := range r.File {
		if f.Mode()&os.ModeSymlink != 0 {
			return errors.New("symlink entries are not permitted")
		}
		target := filepath.Join(root, filepath.Clean("/"+f.Name))
		if !strings.HasPrefix(target, prefix) {
			return fmt.Errorf("archive entry escapes destination: %q", f.Name)
		}
		if f.FileInfo().IsDir() {
			if err := os.MkdirAll(target, 0750); err != nil {
				return err
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(target), 0750); err != nil {
			return err
		}
		if err := writeBoundedFile(f, target); err != nil {
			return err
		}
	}
	return nil
