import {
  ASTNode,
  FragmentDefinitionNode,
  GraphQLError,
  Kind,
  SelectionSetNode,
  ValidationContext,
} from "graphql";

export function createDepthLimitRule(maxDepth = 6) {
  return function depthLimitValidator(context: ValidationContext) {
    const fragments = new Map<string, FragmentDefinitionNode>();
    for (const def of context.getDocument().definitions) {
      if (def.kind === Kind.FRAGMENT_DEFINITION) {
        fragments.set(def.name.value, def);
      }
    }

    function measureDepth(
      selectionSet: SelectionSetNode | undefined,
      depth: number,
      visited: Set<string>
    ): number {
      if (!selectionSet || depth > maxDepth) return depth;
      let deepest = depth;

      for (const sel of selectionSet.selections) {
        if (sel.kind === Kind.FIELD) {
          if (sel.name.value.startsWith("__")) continue;
          deepest = Math.max(deepest, measureDepth(sel.selectionSet, depth + 1, visited));
        } else if (sel.kind === Kind.INLINE_FRAGMENT) {
          deepest = Math.max(deepest, measureDepth(sel.selectionSet, depth, visited));
        } else if (sel.kind === Kind.FRAGMENT_SPREAD) {
          const name = sel.name.value;
          if (visited.has(name)) return maxDepth + 1;
          const frag = fragments.get(name);
          if (frag) {
            const nextVisited = new Set(visited).add(name);
            deepest = Math.max(deepest, measureDepth(frag.selectionSet, depth, nextVisited));
          }
        }
      }
      return deepest;
    }

    return {
      OperationDefinition(node: ASTNode) {
        if (node.kind !== Kind.OPERATION_DEFINITION) return;
        const depth = measureDepth(node.selectionSet, 0, new Set());
        if (depth > maxDepth) {
          context.reportError(
            new GraphQLError(`Query depth ${depth} exceeds maximum allowed depth of ${maxDepth}`)
          );
        }
      },
    };
  };
}
