package rpcserver

import (
	"context"
	"time"

	"google.golang.org/grpc"
)

const (
	maxRecvBytes   = 1 << 20 // 1 MiB
	maxSendBytes   = 2 << 20 // 2 MiB
	maxRPCTimeout  = 5 * time.Second
	maxConcurrency = 256
)

func boundedDeadlineInterceptor(
	ctx context.Context,
	req any,
	_ *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	deadline, ok := ctx.Deadline()
	if !ok || time.Until(deadline) > maxRPCTimeout {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, maxRPCTimeout)
		defer cancel()
	}
	return handler(ctx, req)
}

func NewGRPCServer() *grpc.Server {
	return grpc.NewServer(
		grpc.MaxRecvMsgSize(maxRecvBytes),
		grpc.MaxSendMsgSize(maxSendBytes),
		grpc.MaxConcurrentStreams(maxConcurrency),
		grpc.UnaryInterceptor(boundedDeadlineInterceptor),
	)
}
