import crypto from "crypto";
import { Request, Response } from "express";

function sealPkcePayload(payload: object, keyHex: string): string {
  const key = Buffer.from(keyHex, "hex");
  if (key.length !== 32) {
    throw new Error("PKCE_COOKIE_KEY_HEX must be 32 bytes");
  }
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv("aes-256-gcm", key, iv);
  const ct = Buffer.concat([cipher.update(JSON.stringify(payload), "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return `${iv.toString("base64url")}.${tag.toString("base64url")}.${ct.toString("base64url")}`;
}

export function startOAuthLogin(_req: Request, res: Response): void {
  const keyHex = process.env.PKCE_COOKIE_KEY_HEX ?? "";
  const clientId = process.env.OAUTH_CLIENT_ID ?? "";
  if (!keyHex || !clientId) {
    res.status(500).json({ error: "oauth configuration missing" });
    return;
  }

  const state = crypto.randomBytes(32).toString("base64url");
  const codeVerifier = crypto.randomBytes(32).toString("base64url");
  const codeChallenge = crypto.createHash("sha256").update(codeVerifier).digest("base64url");
  const sealed = sealPkcePayload({ state, codeVerifier, exp: Date.now() + 600_000 }, keyHex);

  res.cookie("__Host-pkce", sealed, {
    httpOnly: true,
    secure: true,
    sameSite: "lax",
    path: "/",
    maxAge: 600_000,
  });

  const authUrl = new URL("https://idp.example.com/oauth2/authorize");
  authUrl.searchParams.set("response_type", "code");
  authUrl.searchParams.set("client_id", clientId);
  authUrl.searchParams.set("code_challenge", codeChallenge);
  authUrl.searchParams.set("code_challenge_method", "S256");
  authUrl.searchParams.set("state", state);
  res.redirect(302, authUrl.toString());
}
