#include <cstddef>
#include <cstdint>
#include <fstream>
#include <limits>
#include <vector>

constexpr std::uint32_t kMaxFrameBytes = 2U * 1024U * 1024U; // 2 MiB

bool read_proto_frame(std::ifstream& in, EnvelopeProto& out) {
    unsigned char len_bytes[4]{};
    in.read(reinterpret_cast<char*>(len_bytes), sizeof(len_bytes));
    if (!in || static_cast<std::size_t>(in.gcount()) != sizeof(len_bytes)) {
        return false;
    }

    const std::uint32_t frame_len =
        (static_cast<std::uint32_t>(len_bytes[0]) << 24) |
        (static_cast<std::uint32_t>(len_bytes[1]) << 16) |
        (static_cast<std::uint32_t>(len_bytes[2]) << 8) |
        static_cast<std::uint32_t>(len_bytes[3]);

    if (frame_len == 0 || frame_len > kMaxFrameBytes ||
        frame_len > static_cast<std::uint32_t>(std::numeric_limits<int>::max())) {
        return false;
    }

    std::vector<char> buf(frame_len);
    in.read(buf.data(), static_cast<std::streamsize>(frame_len));
    if (static_cast<std::size_t>(in.gcount()) != static_cast<std::size_t>(frame_len)) {
        return false;
    }

    return out.ParseFromArray(buf.data(), static_cast<int>(frame_len));
}
