package ratelimit

import (
	"context"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

var quotaScript = redis.NewScript(`
local key = KEYS[1]
local limit = tonumber(ARGV[1])
local window_ms = tonumber(ARGV[2])
local current = redis.call("GET", key)
if not current then
    redis.call("SET", key, limit - 1, "PX", window_ms)
    return {1, limit - 1}
end
local rem = tonumber(current)
if rem <= 0 then
    return {0, 0}
end
local next_rem = redis.call("DECR", key)
return {1, next_rem}
`)

func AllowRequest(
	ctx context.Context,
	rdb *redis.Client,
	key string,
	limit int64,
	window time.Duration,
) (bool, int64, error) {
	if limit <= 0 || window <= 0 {
		return false, 0, fmt.Errorf("invalid limit or window")
	}
	res, err := quotaScript.Run(ctx, rdb, []string{key}, limit, window.Milliseconds()).Int64Slice()
	if err != nil {
		return false, 0, err
	}
	return res[0] == 1, res[1], nil
}
```

