const MAX_RESPONSE_BYTES = 64 * 1024;

export async function dispatchWebhook(
  endpointUrl: string,
  jsonBody: string,
  timeoutMs = 5_000
): Promise<{ status: number; snippet: string }> {
  const res = await fetch(endpointUrl, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: jsonBody,
    redirect: "error",
    signal: AbortSignal.timeout(timeoutMs),
  });

  if (!res.body) {
    return { status: res.status, snippet: "" };
  }

  const reader = res.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_RESPONSE_BYTES) {
        await reader.cancel("Response exceeded byte cap");
        throw new Error("Upstream webhook response too large");
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const merged = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) {
    merged.set(c, offset);
    offset += c.byteLength;
  }
  return {
    status: res.status,
    snippet: new TextDecoder().decode(merged),
  };
}
