```rust
use reqwest::{header, redirect, Client};
use std::time::Duration;

pub fn build_api_client(token: &str) -> Result<Client, Box<dyn std::error::Error>> {
    let mut auth_val = header::HeaderValue::from_str(&format!("Bearer {token}"))?;
    auth_val.set_sensitive(true);

    let mut headers = header::HeaderMap::new();
    headers.insert(header::AUTHORIZATION, auth_val);

    let redirect_policy = redirect::Policy::custom(|attempt| {
        if attempt.previous().len() >= 5 {
            return attempt.error("too many redirects");
        }
        let origin_host = attempt.previous().first().and_then(|u| u.host_str());
        let next_host = attempt.url().host_str();
        if attempt.url().scheme() != "https" || origin_host != next_host {
            return attempt.stop();
        }
        attempt.follow()
    });

    let client = Client::builder()
        .https_only(true)
        .redirect(redirect_policy)
        .default_headers(headers)
        .timeout(Duration::from_secs(15))
        .build()?;

    Ok(client)
}
```

