package auth

import (
	"net/http"
	"net/url"
)

func FinishLoginRedirect(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("return_to")
	u, err := url.Parse(target)
	if err != nil || target == "" {
		http.Redirect(w, r, "/app", http.StatusFound)
		return
	}
	http.Redirect(w, r, u.String(), http.StatusFound)
}
```

