```go
package auth

import (
	"net/http"
	"net/url"
	"strings"
)

var allowedRedirectHosts = map[string]struct{}{
	"console.example.com": {},
	"billing.example.com": {},
}

func safeRedirectTarget(raw string) string {
	if raw == "" || strings.ContainsAny(raw, "\\\r\n") {
		return "/app"
	}
	u, err := url.Parse(raw)
	if err != nil {
		return "/app"
	}
	if u.Scheme == "" && u.Host == "" && u.Opaque == "" {
		if strings.HasPrefix(u.Path, "/") && !strings.HasPrefix(u.Path, "//") {
			return u.RequestURI()
		}
		return "/app"
	}
	if u.Scheme == "https" && u.User == nil {
		if _, ok := allowedRedirectHosts[strings.ToLower(u.Hostname())]; ok {
			return u.String()
		}
	}
	return "/app"
}

func FinishLoginRedirect(w http.ResponseWriter, r *http.Request) {
	target := safeRedirectTarget(r.URL.Query().Get("return_to"))
	http.Redirect(w, r, target, http.StatusSeeOther)
}
