```ts
import { ApolloServer, ApolloServerPlugin } from "@apollo/server";
import { FragmentDefinitionNode, GraphQLError, Kind, SelectionSetNode } from "graphql";

function queryBudgetPlugin(maxDepth = 7, maxFields = 60): ApolloServerPlugin {
  return {
    async requestDidStart() {
      return {
        async didResolveOperation(ctx) {
          if (!ctx.operation) return;
          const fragments = new Map<string, FragmentDefinitionNode>();
          for (const def of ctx.document.definitions) {
            if (def.kind === Kind.FRAGMENT_DEFINITION) {
              fragments.set(def.name.value, def);
            }
          }
          let fieldCount = 0;
          const walk = (set: SelectionSetNode | undefined, depth: number, seen: Set<string>): void => {
            if (!set) return;
            if (depth > maxDepth) {
              throw new GraphQLError(`Query depth exceeds limit of ${maxDepth}`);
            }
            for (const sel of set.selections) {
              if (sel.kind === Kind.FIELD) {
                fieldCount += 1;
                if (fieldCount > maxFields) {
                  throw new GraphQLError(`Query field budget exceeds limit of ${maxFields}`);
                }
                walk(sel.selectionSet, depth + 1, seen);
              } else if (sel.kind === Kind.INLINE_FRAGMENT) {
                walk(sel.selectionSet, depth, seen);
              } else if (sel.kind === Kind.FRAGMENT_SPREAD) {
                const name = sel.name.value;
                if (seen.has(name)) continue;
                const nextSeen = new Set(seen);
                nextSeen.add(name);
                walk(fragments.get(name)?.selectionSet, depth, nextSeen);
              }
            }
          };
          walk(ctx.operation.selectionSet, 1, new Set());
        },
      };
    },
  };
}

export function createGraphqlServer(typeDefs: string, resolvers: Record<string, unknown>) {
  return new ApolloServer({
    typeDefs,
    resolvers,
    introspection: process.env.NODE_ENV !== "production",
    plugins: [queryBudgetPlugin(7, 60)],
  });
}
```

