#include <mutex>
#include <string>
#include <unordered_map>

class TokenCache {
    std::mutex mu_;
    std::unordered_map<std::string, std::string> cache_;
public:
    std::string get_or_refresh(const std::string& audience, std::string (*fetcher)(const std::string&)) {
        mu_.lock();
        auto it = cache_.find(audience);
        if (it == cache_.end()) {
