#include <mutex>
#include <string>
#include <unordered_map>
#include <utility>

class TokenCache {
    std::mutex mu_;
    std::unordered_map<std::string, std::string> cache_;

public:
    std::string get_or_refresh(
        const std::string& audience,
        std::string (*fetcher)(const std::string&)
    ) {
        {
            std::lock_guard<std::mutex> lock(mu_);
            auto it = cache_.find(audience);
            if (it != cache_.end()) {
                return it->second;
            }
        }

        std::string fresh = fetcher(audience);

        std::lock_guard<std::mutex> lock(mu_);
        auto [it, inserted] = cache_.emplace(audience, std::move(fresh));
        return it->second;
    }
};
```

