use serde::de::{self, Deserializer, SeqAccess, Visitor};
use serde::Deserialize;
use std::fmt;
use std::io::{self, Read};

const MAX_BODY_BYTES: u64 = 256 * 1024;
const MAX_BATCH_EVENTS: usize = 128;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct WebhookBatch {
    pub source: String,
    #[serde(default, deserialize_with = "deserialize_bounded_events")]
    pub events: Vec<String>,
}

fn deserialize_bounded_events<'de, D>(deserializer: D) -> Result<Vec<String>, D::Error>
where
    D: Deserializer<'de>,
{
    struct BoundedVecVisitor;

    impl<'de> Visitor<'de> for BoundedVecVisitor {
        type Value = Vec<String>;

        fn expecting(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "a sequence of at most {} event strings", MAX_BATCH_EVENTS)
        }

        fn visit_seq<A>(self, mut seq: A) -> Result<Self::Value, A::Error>
        where
            A: SeqAccess<'de>,
        {
            let cap = seq.size_hint().unwrap_or(0).min(MAX_BATCH_EVENTS);
            let mut out = Vec::with_capacity(cap);
            while let Some(item) = seq.next_element::<String>()? {
                if out.len() >= MAX_BATCH_EVENTS {
                    return Err(de::Error::custom("events array exceeds maximum batch size"));
                }
                out.push(item);
            }
            Ok(out)
        }
    }

    deserializer.deserialize_seq(BoundedVecVisitor)
}

pub fn decode_batch<R: Read>(reader: R) -> io::Result<WebhookBatch> {
    let mut limited = reader.take(MAX_BODY_BYTES + 1);
    let mut buf = Vec::new();
    limited.read_to_end(&mut buf)?;
    if buf.len() as u64 > MAX_BODY_BYTES {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "payload exceeds maximum size"));
    }
    serde_json::from_slice(&buf).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))
}
