			if err != nil {
				return err
			}
			n, copyErr := io.Copy(f, io.LimitReader(tr, hdr.Size+1))
			closeErr := f.Close()
			if copyErr != nil {
				return copyErr
			}
			if closeErr != nil {
				return closeErr
			}
			totalWritten += n
			if n > hdr.Size || totalWritten > maxArchiveBytes {
				return errors.New("tar entry exceeded declared or total byte limit")
			}
		case tar.TypeSymlink, tar.TypeLink:
			return fmt.Errorf("links forbidden in archive: %q", hdr.Name)
