export interface Env {
  WEBHOOK_SECRET: string;
}

const MAX_SKEW_MS = 5 * 60 * 1000;

function decodeHexStrict(hex: string): Uint8Array | null {
  if (hex.length !== 64 || !/^[0-9a-fA-F]+$/.test(hex)) {
    return null;
  }
  const out = new Uint8Array(32);
  for (let i = 0; i < 32; i++) {
    out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const sigHex = req.headers.get("x-webhook-sig") ?? "";
    const tsHeader = req.headers.get("x-webhook-ts") ?? "";
    const sentSecs = Number(tsHeader);
    if (!Number.isInteger(sentSecs) || Math.abs(Date.now() - sentSecs * 1000) > MAX_SKEW_MS) {
      return new Response("stale or invalid timestamp", { status: 401 });
    }

    const sigBytes = decodeHexStrict(sigHex);
    if (!sigBytes || !env.WEBHOOK_SECRET) {
      return new Response("unauthorized", { status: 401 });
    }

    const rawBody = new Uint8Array(await req.arrayBuffer());
    const enc = new TextEncoder();
    const prefix = enc.encode(`${sentSecs}.`);
    const signedPayload = new Uint8Array(prefix.length + rawBody.length);
    signedPayload.set(prefix, 0);
    signedPayload.set(rawBody, prefix.length);

    const key = await crypto.subtle.importKey(
      "raw",
      enc.encode(env.WEBHOOK_SECRET),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["verify"]
    );

    const ok = await crypto.subtle.verify("HMAC", key, sigBytes, signedPayload);
    if (!ok) {
      return new Response("unauthorized", { status: 401 });
    }
    return new Response("ok", { status: 200 });
  },
};
```

