#include <stdexcept>
#include <string>
#include <vector>

std::vector<std::string> load_socket_acl(FILE* fp) {
    if (fp == nullptr) {
        throw std::invalid_argument("null file pointer");
    }
    std::vector<std::string> paths;
    char buf[128];

    while (std::fgets(buf, sizeof(buf), fp) != nullptr) {
        std::size_t len = std::strlen(buf);
        const bool has_newline = (len > 0 && buf[len - 1] == '\n');
        if (!has_newline && !std::feof(fp)) {
