export interface ReplayStore {
  consumeOnce(jti: string, ttlSeconds: number): Promise<boolean>;
}

const ALLOWED_ALGS = ["ES256", "EdDSA"];
const MAX_DPOP_AGE_SECS = 60;

function normalizeHtu(rawUrl: string): string {
  const u = new URL(rawUrl);
  u.search = "";
  u.hash = "";
  return u.toString();
