package s3cfg

import (
	"context"
	"fmt"
	"io"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/s3"
)

const maxConfigBytes int64 = 512 * 1024 // 512 KiB

func FetchTenantConfig(ctx context.Context, client *s3.Client, bucket, key string) ([]byte, error) {
	out, err := client.GetObject(ctx, &s3.GetObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return nil, err
	}
	defer out.Body.Close()

	if out.ContentLength != nil && *out.ContentLength > maxConfigBytes {
		return nil, fmt.Errorf("s3 object exceeds %d bytes", maxConfigBytes)
	}

	data, err := io.ReadAll(io.LimitReader(out.Body, maxConfigBytes+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maxConfigBytes {
		return nil, fmt.Errorf("s3 stream exceeded %d bytes", maxConfigBytes)
	}
	return data, nil
}
