#include <sys/stat.h>
#include <unistd.h>
#include <stdexcept>
#include <string>

std::string load_secret_cred(const std::string& cred_dir, const std::string& name) {
    if (name.empty() || name == "." || name == ".." || name.find('/') != std::string::npos) {
        throw std::invalid_argument("invalid credential name");
    }

