        close(fd);
        throw std::runtime_error("credential must be a bounded regular file");
    }

    std::string out(static_cast<std::size_t>(st.st_size), '\0');
    std::size_t total = 0;
    while (total < out.size()) {
        const ssize_t n = read(fd, out.data() + total, out.size() - total);
        if (n <= 0) {
            close(fd);
            throw std::runtime_error("short or failed credential read");
        }
        total += static_cast<std::size_t>(n);
    }
    close(fd);
