}

export function verifyOAuthState(req: Request, res: Response): boolean {
  const cookieState = req.cookies?.[STATE_COOKIE];
  res.clearCookie(STATE_COOKIE, { httpOnly: true, secure: true, sameSite: "lax", path: "/" });

  const queryState = req.query.state;
  if (typeof queryState !== "string" || typeof cookieState !== "string") {
    return false;
  }
  if (queryState.length === 0 || queryState.length !== cookieState.length) {
    return false;
  }
  const a = Buffer.from(queryState, "utf8");
  const b = Buffer.from(cookieState, "utf8");
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
