const MAX_INFLIGHT_TASKS: usize = 32;
const SEND_TIMEOUT: Duration = Duration::from_secs(2);

pub fn spawn_event_fanout(events: Vec<Vec<u8>>) -> mpsc::Receiver<Vec<u8>> {
