class HmacKeyring:
    active_kid: str
    keys: dict[str, bytes]
    previous_kid: str | None = None

    def __post_init__(self) -> None:
        if self.active_kid not in self.keys or len(self.keys[self.active_kid]) < 32:
            raise ValueError("active_kid must reference a >= 32-byte key")
        if self.previous_kid is not None:
            if self.previous_kid not in self.keys or len(self.keys[self.previous_kid]) < 32:
                raise ValueError("previous_kid must reference a >= 32-byte key")

