use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use jsonwebtoken::{decode, Algorithm, DecodingKey, TokenData, Validation};
use serde::Deserialize;

const MIN_RSA_MODULUS_BYTES: usize = 256; // 2048 bits

#[derive(Debug, Deserialize)]
pub struct Claims {
    pub sub: String,
    pub iss: String,
    pub aud: String,
    pub exp: usize,
}

pub fn verify_rs256_jwk(
    token: &str,
    n_b64: &str,
    e_b64: &str,
    expected_iss: &str,
    expected_aud: &str,
) -> Result<TokenData<Claims>, String> {
    let mod_bytes = URL_SAFE_NO_PAD
        .decode(n_b64)
        .map_err(|_| "invalid base64url RSA modulus".to_string())?;
    let significant = mod_bytes.iter().skip_while(|&&b| b == 0).count();
    if significant < MIN_RSA_MODULUS_BYTES {
        return Err("RSA modulus shorter than 2048 bits".to_string());
    }

    let key = DecodingKey::from_rsa_components(n_b64, e_b64)
        .map_err(|e| format!("invalid RSA components: {e}"))?;

    let mut validation = Validation::new(Algorithm::RS256);
    validation.set_issuer(&[expected_iss]);
    validation.set_audience(&[expected_aud]);
    validation.set_required_spec_claims(&["exp", "iss", "aud", "sub"]);
    validation.leeway = 30;

    decode::<Claims>(token, &key, &validation).map_err(|e| format!("jwt verification failed: {e}"))
}
