import socket
import struct

HEADER_STRUCT = struct.Struct(">I")
MAX_FRAME_BYTES = 1024 * 1024  # 1 MiB


def recv_exact(sock: socket.socket, size: int) -> bytes:
    if size < 0:
        raise ValueError("size must be non-negative")
    buf = bytearray(size)
    view = memoryview(buf)
    offset = 0
    while offset < size:
        n = sock.recv_into(view[offset:], size - offset)
        if n == 0:
            raise EOFError("unexpected EOF while reading binary frame")
        offset += n
    return bytes(buf)


def read_frame(sock: socket.socket) -> bytes:
    raw_hdr = recv_exact(sock, HEADER_STRUCT.size)
    (length,) = HEADER_STRUCT.unpack(raw_hdr)
    if length == 0 or length > MAX_FRAME_BYTES:
        raise ValueError(f"frame length {length} outside allowed bounds")
    return recv_exact(sock, length)
