        return Err(SplitError::NegativeGross);
    }
    if shares_bps.is_empty() {
        return Err(SplitError::EmptyShares);
    }
    let total_bps: u32 = shares_bps.iter().map(|&b| u32::from(b)).sum();
    if total_bps != 10_000 {
        return Err(SplitError::InvalidBpsTotal);
    }

    let gross = i128::from(gross_cents);
    let mut allocations = Vec::with_capacity(shares_bps.len());
    let mut remainders = Vec::with_capacity(shares_bps.len());
    let mut allocated_sum: i128 = 0;

    for (idx, &bps) in shares_bps.iter().enumerate() {
        let prod = gross * i128::from(bps);
        let base = prod / 10_000;
        let rem = prod % 10_000;
        allocations.push(base as i64);
        remainders.push((rem, idx));
        allocated_sum += base;
    }

    let leftover = (gross - allocated_sum) as usize;
    remainders.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    for &(_, idx) in remainders.iter().take(leftover) {
        allocations[idx] += 1;
    }

