	pInfo, err := os.Lstat(parentDir)
	if err != nil {
		return nil, err
	}
	if pInfo.Mode()&fs.ModeSymlink != 0 || pInfo.Mode().Perm() != 0o700 {
		return nil, errors.New("socket parent directory must be a non-symlink 0700 directory")
	}

	if info, err := os.Lstat(cleanPath); err == nil {
		if info.Mode()&fs.ModeSocket == 0 {
