import { createRemoteJWKSet, JWTPayload, jwtVerify } from "jose";

const LOGOUT_EVENT_URI = "http://schemas.openid.net/event/backchannel-logout";

export interface VerifiedLogoutClaims extends JWTPayload {
  jti: string;
  sub?: string;
  sid?: string;
}

export async function verifyLogoutToken(
  logoutToken: string,
  jwks: ReturnType<typeof createRemoteJWKSet>,
  issuer: string,
  clientId: string,
): Promise<VerifiedLogoutClaims> {
  const { payload } = await jwtVerify(logoutToken, jwks, {
    issuer,
    audience: clientId,
    algorithms: ["RS256", "ES256"],
    clockTolerance: 30,
    maxTokenAge: "5m",
  });

  if ("nonce" in payload) {
    throw new Error("logout_token must not contain a nonce claim");
  }
  const events = payload.events as Record<string, unknown> | undefined;
  const logoutEvent = events?.[LOGOUT_EVENT_URI];
  if (!logoutEvent || typeof logoutEvent !== "object" || Array.isArray(logoutEvent)) {
    throw new Error("missing backchannel-logout event claim");
  }
  const hasSub = typeof payload.sub === "string" && payload.sub.length > 0;
  const hasSid = typeof payload.sid === "string" && payload.sid.length > 0;
  if (!hasSub && !hasSid) {
    throw new Error("logout_token must contain sub or sid");
  }
  if (typeof payload.jti !== "string" || payload.jti.length === 0) {
    throw new Error("logout_token missing jti");
  }

  return payload as VerifiedLogoutClaims;
}
