    std::condition_variable cv_;
    std::queue<Conn> pool_;
    bool stopped_ = false;

public:
    std::optional<Conn> acquire() {
        std::unique_lock<std::mutex> lock(mu_);
        cv_.wait(lock, [this] { return stopped_ || !pool_.empty(); });
        if (pool_.empty()) {
