use bytes::BytesMut;
use futures_util::StreamExt;
use std::collections::HashSet;
use std::io;
use tokio::net::UnixStream;
use tokio_util::codec::{FramedRead, LengthDelimitedCodec};

const MAX_IPC_FRAME_BYTES: usize = 64 * 1024;

pub async fn read_ipc_command(
    stream: UnixStream,
    allowed_uids: &HashSet<u32>,
) -> io::Result<BytesMut> {
    let cred = stream.peer_cred()?;
    if !allowed_uids.contains(&cred.uid()) {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            "caller UID is not authorized",
        ));
    }

    let codec = LengthDelimitedCodec::builder()
        .length_field_length(4)
        .max_frame_length(MAX_IPC_FRAME_BYTES)
        .new_codec();

    let mut reader = FramedRead::new(stream, codec);
    match reader.next().await {
        Some(Ok(frame)) => Ok(frame),
        Some(Err(err)) => Err(err),
        None => Err(io::Error::new(io::ErrorKind::UnexpectedEof, "empty IPC stream")),
    }
}
