const STRIPPED_HEADERS = [
  "x-original-url",
  "x-rewrite-url",
  "x-forwarded-host",
];

function sanitizeUpstreamRequest(req: Request): Request {
  const headers = new Headers(req.headers);
  for (const h of STRIPPED_HEADERS) {
    headers.delete(h);
  }
  return new Request(req.url, {
    method: req.method,
    headers,
    body: req.method === "GET" || req.method === "HEAD" ? null : req.body,
    redirect: "manual",
  });
}

export default {
  async fetch(req: Request, _env: unknown, ctx: ExecutionContext): Promise<Response> {
    const cleanReq = sanitizeUpstreamRequest(req);
    const hasCredentials =
      cleanReq.headers.has("authorization") || cleanReq.headers.has("cookie");

    if (cleanReq.method !== "GET" || hasCredentials) {
      const res = await fetch(cleanReq);
      const outHeaders = new Headers(res.headers);
      if (hasCredentials) {
        outHeaders.set("Cache-Control", "private, no-store");
      }
      return new Response(res.body, { status: res.status, headers: outHeaders });
    }

    const url = new URL(cleanReq.url);
    const cacheKey = new Request(url.toString(), { method: "GET" });
    const cache = caches.default;
    const hit = await cache.match(cacheKey);
    if (hit) {
      return hit;
    }

    const upstreamRes = await fetch(cleanReq);
    const cc = (upstreamRes.headers.get("cache-control") ?? "").toLowerCase();
    if (
      upstreamRes.status === 200 &&
      !upstreamRes.headers.has("set-cookie") &&
      cc.includes("public") &&
      !cc.includes("no-store") &&
      !cc.includes("private")
    ) {
      ctx.waitUntil(cache.put(cacheKey, upstreamRes.clone()));
    }
    return upstreamRes;
  },
};
