#include <charconv>
#include <cstdint>
#include <limits>
#include <optional>
#include <string_view>

std::optional<int64_t> parse_price_pips(std::string_view raw) noexcept {
    if (raw.empty() || raw.front() == '-' || raw.front() == '+') {
        return std::nullopt;
    }

    const std::size_t dot = raw.find('.');
    const std::string_view whole_part = (dot == std::string_view::npos) ? raw : raw.substr(0, dot);
    const std::string_view frac_part  = (dot == std::string_view::npos) ? std::string_view{} : raw.substr(dot + 1);

    if (whole_part.empty() || frac_part.size() > 4 || (dot != std::string_view::npos && frac_part.empty())) {
