    }

    uint64_t whole = 0;
    const auto [w_ptr, w_ec] = std::from_chars(
        whole_part.data(),
        whole_part.data() + whole_part.size(),
        whole,
        10
    );
    if (w_ec != std::errc{} || w_ptr != whole_part.data() + whole_part.size()) {
        return std::nullopt;
    }

    uint64_t frac = 0;
    if (!frac_part.empty()) {
        const auto [f_ptr, f_ec] = std::from_chars(
            frac_part.data(),
            frac_part.data() + frac_part.size(),
            frac,
            10
        );
        if (f_ec != std::errc{} || f_ptr != frac_part.data() + frac_part.size()) {
            return std::nullopt;
        }
        for (std::size_t i = frac_part.size(); i < 4; ++i) {
            frac *= 10;
        }
    }

    constexpr uint64_t scale = 10000ULL;
    constexpr uint64_t max_i64 = static_cast<uint64_t>(std::numeric_limits<int64_t>::max());
    if (whole > (max_i64 - frac) / scale) {
        return std::nullopt;
    }
    return static_cast<int64_t>(whole * scale + frac);
}
