Our C++ webhook worker queue uses an unbounded `std::queue` and bare `cv.wait(lk)`, risking OOM during traffic bursts, spurious-wakeup crashes on `front()`, and hung threads on shutdown when `notify_one()` only wakes one worker:

```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <string>

class WorkQueue {
    std::mutex mtx_;
    std::condition_variable cv_;
    std::queue<std::string> q_;
public:
    void push(std::string item) {
        std::unique_lock<std::mutex> lk(mtx_);
        q_.push(std::move(item));
        cv_.notify_one();
    }
    std::string pop() {
        std::unique_lock<std::mutex> lk(mtx_);
        cv_.wait(lk);
        std::string out = std::move(q_.front());
        q_.pop();
        return out;
    }
};
