```cpp
#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>
#include <string>
#include <utility>

class WorkQueue {
    std::mutex mtx_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    std::queue<std::string> q_;
    std::size_t max_cap_;
    bool closed_ = false;

public:
    explicit WorkQueue(std::size_t max_cap) : max_cap_(max_cap) {
        if (max_cap_ == 0) {
            throw std::invalid_argument("max_cap must be positive");
        }
    }

    bool push(std::string item) {
        std::unique_lock<std::mutex> lk(mtx_);
        not_full_.wait(lk, [this] { return closed_ || q_.size() < max_cap_; });
        if (closed_) {
            return false;
        }
        q_.push(std::move(item));
        not_empty_.notify_one();
        return true;
    }

    std::optional<std::string> pop() {
        std::unique_lock<std::mutex> lk(mtx_);
        not_empty_.wait(lk, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) {
            return std::nullopt;
        }
        std::string out = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return out;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lk(mtx_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }
};
